ALTER TABLE public.ride_requests ADD COLUMN confirmed_driver_end_time time;
DO $$ DECLARE body text;BEGIN SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='confirmed_provider_driver_guard';body:=replace(body,'END IF;END IF;RETURN NEW;', 'END IF; IF NEW.confirmed_driver_end_time IS NULL OR NEW.confirmed_driver_end_time<=NEW.pickup_time::time THEN RAISE EXCEPTION ''Review a driver end time after pickup''; END IF; PERFORM 1 FROM public.workspaces WHERE id=NEW.workspace_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.trips x WHERE x.driver_id=NEW.confirmed_provider_driver_id AND x.status NOT IN (''completed'',''canceled'',''cancelled'',''no_show'') AND x.pickup_date+coalesce(x.scheduled_start_time,x.pickup_time)<NEW.pickup_date+NEW.confirmed_driver_end_time AND coalesce(x.pickup_date+x.assignment_end_time,CASE WHEN x.estimated_duration_seconds>0 THEN x.pickup_date+coalesce(x.scheduled_start_time,x.pickup_time)+make_interval(secs=>x.estimated_duration_seconds) END,(x.pickup_date+1)::timestamp)>NEW.pickup_date+NEW.pickup_time::time) THEN RAISE EXCEPTION ''Suggested driver has a time conflict; nothing submitted''; END IF; END IF;RETURN NEW;');EXECUTE body;
SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='create_owned_provider_operation';body:=replace(body,'UPDATE public.trips SET driver_id=NEW.confirmed_provider_driver_id WHERE id=tid;', 'PERFORM set_config(''app.resource_assignment_trip'',tid::text,true); UPDATE public.trips SET driver_id=NEW.confirmed_provider_driver_id,scheduled_start_time=NEW.pickup_time::time,assignment_end_time=NEW.confirmed_driver_end_time WHERE id=tid; PERFORM set_config(''app.resource_assignment_trip'','''',true);');EXECUTE body;
SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='patient_trip_event_notification';body:=replace(body,'IF TG_TABLE_NAME=', 'IF TG_TABLE_NAME=''trips'' AND current_setting(''app.resource_assignment_trip'',true)=NEW.id::text THEN RETURN NEW;END IF; IF TG_TABLE_NAME=');EXECUTE body;
SELECT pg_get_functiondef(oid) INTO body FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='attach_confirmed_customer_invoice';body:=replace(body,'IF q->>''facilityAgreementId'' IS NOT NULL THEN', 'IF q->''requestBinding'' IS NOT NULL AND q->''requestBinding'' IS DISTINCT FROM jsonb_build_object(''savedPatientId'',NEW.saved_patient_id,''payerId'',NEW.payer_id,''coordinationContactId'',NEW.coordination_contact_id,''passengerCount'',NEW.passenger_count,''wheelchairPositions'',NEW.wheelchair_positions,''patientFirstName'',NEW.patient_first_name,''patientLastName'',NEW.patient_last_name,''patientPhone'',NEW.patient_phone,''appointmentTime'',left(coalesce(NEW.appointment_time,''''),5),''returnDropoffTime'',left(coalesce(NEW.return_dropoff_time,''''),5),''billingSource'',NEW.trip_billing_source,''billingFirstName'',NEW.trip_billing_first_name,''billingLastName'',NEW.trip_billing_last_name,''billingEmail'',NEW.trip_billing_email,''billingPhone'',NEW.trip_billing_phone) THEN RAISE EXCEPTION ''Patient, payer, contact, capacity or time changed; review a fresh quote'';END IF; IF q->>''facilityAgreementId'' IS NOT NULL THEN');EXECUTE body;END $$;